        assert_eq!(soc.read32(0x0207_1000), 0xaaaa_aaaa, "the next sector as installed");
        assert_eq!(soc.flash.revision, 2, "erase and program persist even after XIP consumes changed");
        assert!(!soc.flash.busy());
    }

