        Some((0..len).map(|i| fm1_core::Bus::read8(&mut self.soc, addr + i)).collect())
    }

    pub fn word(&mut self, addr: u32) -> Option<u32> {
        self.read_ram(addr, 4).map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
    }
}

