8:pub mod golden;
9:pub mod machine;
10:pub mod midi;
11:pub mod run;
12:pub mod script;
13:
14:use formats::{Case, Json};
15:use run::{Options, Outcome, When};
16:use std::path::{Path, PathBuf};
17:
18:/// The vendored emulator's upstream commit (vendor/emulator/UPSTREAM.md).
19:pub const EMULATOR_COMMIT: &str = "43ed5580064885e93bc8d20be931ae950d10cd4f";
20:
21:pub mod exit {
22:    pub const OK: i32 = 0;
23:    pub const GOLDEN_MISMATCH: i32 = 1;
24:    pub const USAGE: i32 = 2;
25:    pub const FAULT: i32 = 3;
26:    pub const HALT: i32 = 4;
27:    pub const HANG: i32 = 5;
28:}
29:
30:pub const USAGE: &str = "\
31:usage:
32:  fwtest run IMAGE --ms MS --out DIR [options]
33:  fwtest suite FILE --out DIR
34:  fwtest version
35:
36:run options:
37:  --script FILE          timed inputs (keys, encoders, pot, MIDI)
38:  --flash FILE           initial contents of the flash chip
39:  --ram ADDR:LEN@WHEN    save LEN bytes of RAM at ADDR (hex with 0x, or decimal)
40:  --lcd WHEN             save the screen as PNG
41:  --leds-every MS        sample the LEDs every MS into leds.csv
42:  --flash-out            save the flash chip at the end (flash.bin)
43:  --flash-log            the erases and programs started (flash-ops.csv)
44:  --power-cut MS         end the run at MS as a power cut, saving flash.bin
45:  --wav                  save the audio output (audio.wav)
46:  --ipb                  instructions per audio block (ipb.csv)
47:  --console              save the debug console bytes (console.txt)
48:  --midi-out             save the MIDI output (midi-out.csv, midi-out.txt)
49:  --watchdog ADDR:MS     a hang if the word at ADDR stays the same for MS
50:  --halt-ok              a halt counts as success
51:  --golden DIR           compare the outputs with the golden files in DIR
52:WHEN is a time in ms (up to three decimals) or `end`.";
53:
54:/// Removes every FM1_* variable: upstream reads several to switch traces and
55:/// execution paths, which would break determinism (machine.rs).
56:pub fn scrub_environment() {
