89:pub fn parse_run(args: &[String], base: &Path) -> Result<RunArgs, String> {
90:    let mut image = None;
91:    let mut out = None;
92:    let mut golden = None;
93:    let mut script_path = None;
94:    let mut ms = None;
95:    let mut opt = Options::default();
96:    let mut flash = None;
97:    let mut it = args.iter();
98:    let path = |s: &String| base.join(s);
99:    while let Some(a) = it.next() {
100:        let mut val = |name: &str| it.next().cloned().ok_or_else(|| format!("{name} needs a value"));
101:        match a.as_str() {
102:            "--ms" => {
103:                if ms.is_some() {
104:                    return Err(if opt.power_cut { "--power-cut sets the run's end: give it or --ms, not both" } else { "--ms given twice" }.into());
105:                }
106:                ms = Some(script::parse_ms(&val("--ms")?)?)
107:            }
108:            "--out" => out = Some(path(&val("--out")?)),
109:            "--script" => script_path = Some(path(&val("--script")?)),
110:            "--flash" => flash = Some(path(&val("--flash")?)),
111:            "--golden" => golden = Some(path(&val("--golden")?)),
112:            "--ram" => {
113:                let v = val("--ram")?;
114:                let (al, w) = v.split_once('@').ok_or("--ram needs ADDR:LEN@WHEN")?;
115:                let (a, l) = al.split_once(':').ok_or("--ram needs ADDR:LEN@WHEN")?;
116:                opt.ram.push((number(a)?, number(l)?, When::parse(w)?));
117:            }
118:            "--lcd" => opt.lcd.push(When::parse(&val("--lcd")?)?),
119:            "--leds-every" => {
120:                let us = script::parse_ms(&val("--leds-every")?)?;
121:                if us == 0 {
122:                    return Err("--leds-every must be more than 0".into());
123:                }
124:                opt.leds_every_us = Some(us);
125:            }
126:            "--watchdog" => {
127:                let v = val("--watchdog")?;
128:                let (a, m) = v.split_once(':').ok_or("--watchdog needs ADDR:MS")?;
129:                opt.watchdog = Some((number(a)?, number(m)? as u64));
130:            }
131:            "--flash-out" => opt.flash_out = true,
132:            "--flash-log" => opt.flash_log = true,
133:            "--power-cut" => {
134:                if ms.is_some() {
135:                    return Err(if opt.power_cut { "--power-cut given twice" } else { "--power-cut sets the run's end: give it or --ms, not both" }.into());
136:                }
137:                ms = Some(script::parse_ms(&val("--power-cut")?)?);
138:                opt.power_cut = true;
139:            }
140:            "--wav" => opt.wav = true,
141:            "--ipb" => opt.ipb = true,
142:            "--console" => opt.console = true,
143:            "--midi-out" => opt.midi_out = true,
144:            "--halt-ok" => opt.halt_ok = true,
145:            s if s.starts_with("--") => return Err(format!("unknown option {s}")),
146:            s if image.is_none() => image = Some(path(&s.to_string())),
147:            s => return Err(format!("unexpected argument {s:?}")),
148:        }
149:    }
150:    opt.ms_us = ms.ok_or("--ms (or --power-cut) is required")?;
151:    if opt.ms_us == 0 {
152:        return Err("--ms must be more than 0".into());
153:    }
154:    if let Some(f) = flash {
155:        opt.flash_in = Some(read(&f, "flash file")?);
156:    }
157:    if let Some(s) = &script_path {
158:        let text = String::from_utf8(read(s, "script")?).map_err(|_| "the script is not UTF-8 text".to_string())?;
159:        opt.script = script::parse(&text)?;
160:    }
161:    opt.lcd.sort();
162:    opt.lcd.dedup();
163:    Ok(RunArgs { image: image.ok_or("IMAGE is required")?, out: out.ok_or("--out is required")?, golden, script: script_path, opt })
164:}
