174:/// Runs, writes the outputs, result.json and junit.xml into `out`.
175:pub fn execute(a: &RunArgs, suite_name: &str) -> Result<Done, String> {
176:    let image = read(&a.image, "image")?;
177:    let report = run::run(&image, &a.opt)?;
178:    prepare_out(&a.out)?;
179:    for o in &report.outputs {
180:        std::fs::write(a.out.join(&o.name), &o.data).map_err(|e| format!("cannot write {}: {e}", o.name))?;
181:    }
182:    let outs: Vec<(String, Vec<u8>)> = report.outputs.iter().map(|o| (o.name.clone(), o.data.clone())).collect();
183:    let checks = match &a.golden {
184:        Some(d) => golden::check(d, &outs)?,
185:        None => Vec::new(),
186:    };
187:    let mismatch = checks.iter().any(|c| c.problem.is_some());
188:    let exit = match &report.outcome {
189:        Outcome::Fault { .. } => exit::FAULT,
190:        Outcome::Hang { .. } => exit::HANG,
191:        _ if mismatch => exit::GOLDEN_MISMATCH,
192:        Outcome::Halt { .. } if !a.opt.halt_ok => exit::HALT,
193:        _ => exit::OK,
194:    };
195:    let mut cases = vec![Case {
196:        name: "run".into(),
197:        failure: match (&report.outcome, a.opt.halt_ok) {
198:            (Outcome::Completed | Outcome::PowerCut { .. }, _) | (Outcome::Halt { .. }, true) => None,
199:            (o, _) => Some(format!("{}: {}", o.name(), o.detail())),
200:        },

