const OUT0: u32 = 0x01c0_0100;
const BOOT_BLOCK: u32 = 0x01c7_fc00;
const AREA: usize = 0x4000;

fn here(p: &str) -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests").join(p)
