fn chip_key(b: &[u8; 32]) -> u16 {
    let mut s = (b[..16].iter().map(|&x| x as u32).sum::<u32>() % 256) as u8;
    if s >= 0xe0 {
        s = 0xaa;
    } else if s <= 0x10 {
        s = 0x55;
    }
    (0..16).filter(|&i| (b[16 + i] ^ b[15 - i]) < s).fold(0, |k, i| k | 1 << i)
